# Pydroid may execute main.py from a temporary location, so the app image
# is embedded in the Python file instead of depending on an external path.
_EMBEDDED_IMAGE_B64 = ""

def prepare_image():
    path = Path(App.get_running_app().user_data_dir) / "deewan.jpg"
    try:
        if not path.exists():
            path.write_bytes(__import__("base64").b64decode(_EMBEDDED_IMAGE_B64))
        return str(path)
    except Exception:
        return ""

# Android system font is available on the device; fall back to default if not.
_SYSTEM_FONT = "/system/fonts/NotoNaskhArabic-Regular.ttf"
FONT_AR = _SYSTEM_FONT if Path(_SYSTEM_FONT).exists() else ""
DB_FILE = None

def get_db_file():
    app = App.get_running_app()
    return Path(app.user_data_dir) / "drakon_users.json"

def ar(text):
    try:
        return arabic_reshaper.reshape(str(text))[::-1]
    except Exception:
        return str(text)

def make_hash(password, salt=None):
    salt = salt or secrets.token_hex(16)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode(), salt.encode(), 120000).hex()
    return salt, digest

def verify(password, salt, digest):
    _, test = make_hash(password, salt)
    return secrets.compare_digest(test, digest)

def load_users():
    db_file = get_db_file()
    if not db_file.exists():
        return {}
    try:
        return json.loads(db_file.read_text(encoding="utf-8"))
    except Exception:
        return {}

def save_users(users):
    db_file = get_db_file()
    db_file.parent.mkdir(parents=True, exist_ok=True)
    db_file.write_text(json.dumps(users, ensure_ascii=False, indent=2), encoding="utf-8")

def create_default_admin():
    users = load_users()
    email = "admin@drakon.com"
    if email not in users:
        salt, digest = make_hash("Admin123")
        users[email] = {
            "email": email,
            "password_salt": salt,
            "password_hash": digest,
            "role": "admin",
            "coins": 0,
            "active": True
        }
        save_users(users)

