Builder.load_string(KV)

class LoginScreen(Screen):
    def login(self):
        app = App.get_running_app()
        email = self.ids.email.text.strip().lower()
        password = self.ids.password.text
        user = load_users().get(email)
        if not user or not verify(password, user["password_salt"], user["password_hash"]):
            app.notice("البريد أو كلمة السر غير صحيحة.")
            return
        if not user.get("active", True):
            app.notice("الحساب معطل.")
            return
        app.current_email = email
        app.current_role = user["role"]
        self.ids.password.text = ""
        app.go("admin" if user["role"] == "admin" else "home")

class RegisterScreen(Screen):
    def create_account(self):
        app = App.get_running_app()
        email = self.ids.email.text.strip().lower()
        password = self.ids.password.text
        if "@" not in email or "." not in email:
            app.notice("اكتبي بريد إلكتروني صحيح.")
            return
        if len(password) < 6:
            app.notice("كلمة السر يجب أن تكون 6 أحرف على الأقل.")
            return
        if password != self.ids.confirm.text:
            app.notice("كلمتا السر غير متطابقتين.")
            return
        users = load_users()
        if email in users:
            app.notice("هذا البريد مستخدم مسبقاً.")
            return
        salt, digest = make_hash(password)
        users[email] = {
            "email": email,
            "password_salt": salt,
            "password_hash": digest,
            "role": "member",
            "coins": 0,
            "active": True
        }
        save_users(users)
        self.ids.email.text = ""
        self.ids.password.text = ""
        self.ids.confirm.text = ""
        app.notice("تم إنشاء الحساب بنجاح.")
        app.go("login")

class HomeScreen(Screen):
    balance = StringProperty("")
    def on_pre_enter(self):
        app = App.get_running_app()
        user = load_users().get(app.current_email, {})
        self.balance = ar(f"رصيد العملات: {user.get('coins', 0)}")

class AdminScreen(Screen):
    balance = StringProperty("")
    def on_pre_enter(self):
        self.refresh()
    def refresh(self):
        app = App.get_running_app()
        if app.current_role != "admin":
            app.go("login")
            return
        users = load_users()
        admin = users.get(app.current_email)
        self.balance = ar(f"رصيد المدير: {admin.get('coins', 0)}")
        box = self.ids.users
        box.clear_widgets()
        members = [(e,u) for e,u in users.items() if u.get("role") == "member"]
        if not members:
            box.add_widget(Label(text=ar("لا يوجد أعضاء حالياً."), font_name=app.font_ar,
                                 size_hint_y=None, height=dp(45)))
        for email, user in members:
            row = BoxLayout(size_hint_y=None, height=dp(55), spacing=dp(6))
            label = Label(
                text=ar(f"{email} | العملات: {user.get('coins',0)}"),
                font_name=app.font_ar,
                color=(.9,.9,.95,1),
                halign="right"
            )
            label.bind(size=lambda inst, val: setattr(inst, "text_size", val))
            from kivy.uix.button import Button
            button = Button(text=ar("إعطاء"), font_name=app.font_ar)
            button.bind(on_release=lambda _, e=email: self.open_give(e))
            row.add_widget(label)
            row.add_widget(button)
            box.add_widget(row)
    def add_self_coins(self):
        app = App.get_running_app()
        if app.current_role != "admin":
            app.go("login")
            return
        users = load_users()
        users[app.current_email]["coins"] += 100
        save_users(users)
        self.refresh()
        app.notice("تمت إضافة 100 عملة للمدير.")
    def open_give(self, email):
        app = App.get_running_app()
        screen = app.sm.get_screen("give_coins")
        screen.target_email = email
        screen.target = ar(f"العضو: {email}")
        app.go("give_coins")

class GiveCoinsScreen(Screen):
    target_email = StringProperty("")
    target = StringProperty("")
    def give(self):
        app = App.get_running_app()
        if app.current_role != "admin":
            app.go("login")
            return
        try:
            amount = int(self.ids.amount.text)
        except ValueError:
            app.notice("اكتبي عدد عملات صحيح.")
            return
        if amount <= 0 or amount > 1000000:
            app.notice("عدد العملات غير صالح.")
            return
        users = load_users()
        if self.target_email not in users or users[self.target_email].get("role") != "member":
            app.notice("العضو غير موجود.")
            return
        users[self.target_email]["coins"] += amount
        save_users(users)
        self.ids.amount.text = ""
        app.notice(f"تم إعطاء {amount} عملة للعضو.")
        app.go("admin")

class SimpleScreen(Screen):
    page_title = StringProperty("")
    page_body = StringProperty("")
    def set_page(self, title, body):
        self.page_title = ar(title)
        self.page_body = ar(body)

class DrakonChat(App):
    font_ar = StringProperty(FONT_AR)
    image_path = StringProperty("")
    current_email = ""
    current_role = ""
    sm = None
    def ar(self, text):
        return ar(text)
    def build(self):
        self.image_path = prepare_image()
        create_default_admin()
        sm = ScreenManager()
        sm.add_widget(LoginScreen(name="login"))
        sm.add_widget(RegisterScreen(name="register"))
        sm.add_widget(HomeScreen(name="home"))
        sm.add_widget(AdminScreen(name="admin"))
        sm.add_widget(GiveCoinsScreen(name="give_coins"))
        for name,title,body in [
            ("messages","الرسائل","هنا تضاف المحادثات وربط السيرفر."),
            ("friends","الأصدقاء","هنا تضاف الأصدقاء."),
            ("gifts","الهدايا","هنا تضاف الهدايا."),
            ("vip","VIP","هنا تضاف باقات VIP."),
            ("profile","الملف الشخصي","هنا تظهر بيانات الحساب.")
        ]:
            page=SimpleScreen(name=name)
            page.set_page(title,body)
            sm.add_widget(page)
        self.sm=sm
        return sm
    def go(self, screen):
        if screen == "admin" and self.current_role != "admin":
            screen = "login"
        if screen not in ("login","register") and not self.current_email:
            screen = "login"
        self.sm.current = screen
    def logout(self):
        self.current_email = ""
        self.current_role = ""
        self.go("login")
    def notice(self, message):
        Popup(
            title="Drakon Chat",
            content=Label(text=ar(message), font_name=FONT_AR, font_size=dp(16)),
            size_hint=(.88,.32)
        ).open()

if __name__ == "__main__":
    DrakonChat().run()
